// Generated by engine/hip/translate.py from engine/cuda/gemv.cu, then patched. Edit src/gemv.cu and
// run `translate.py save gemv.cu` to keep the change; do not edit the rules output by hand.
// Decode GEMV (kernels.h, "Decode GEMV"): y[m, n] = alpha * (sum_k x[m, k] * w[n, k] + bias[n]) + beta * y.
//
// Decode is memory bound: a token streams the whole weight matrix once, so the lane mapping sets the
// cost. A wavefront step covers LX_WARP lanes' words of consecutive k in a row: 4 bf16 or 8 int8 per lane, so
// 128 or 256 k. Lane l's word is contiguous with its neighbours', and every word is 8 bytes, so a warp
// load is one contiguous 256 B run. The x loads for those k are contiguous too, and the RG rows a warp
// owns share them. A lane that owned a whole 16-byte chunk would scatter its x loads 64 B apart across
// lanes, up to 4x the L1 wavefronts for the same work. Weight loads are cache-streaming so that the x
// vector stays in L1. The loads for the next KU steps are in flight while the current ones are
// consumed, and they go before the programmatic-dependent-launch wait, since they do not depend on the
// previous kernel in the stream: the next GEMV starts streaming while this one finishes.
//
// Two kernels:
//   vec    K > 256 with aligned rows: the warps of a row group split the 128-k steps of each row.
//          When N is too small to fill the GPU, S warps split one row group's steps and combine in
//          shared memory in a fixed order, so split-K is deterministic without atomics.
//   small  K <= 256, or misaligned x or w: scalar loads. lpr lanes cover one row, and the 32 / lpr
//          rows of a warp reduce with xor shuffles inside their group.
// The int8 row scale is applied once per row: sum_k x * (q * s) = s * sum_k x * q.

#include "lx_hip.h"

#include <type_traits>

#include "common.cuh"
#include "kernels.h"

namespace {

using bf16 = __hip_bfloat16;

constexpr int kThreads = 256;  // vec kernel: 8 warps per block
constexpr int kWarps = kThreads / LX_WARP;  // wavefronts per block (device code; host: warps_per_block())
constexpr int kMaxM = 8;
constexpr int kSmallK = 256;       // rows this short are cheaper as scalar loads
constexpr int kWarpTarget = 2048;  // warps wanted before K is split across warps

// Wavefronts per block on the current device (the vec kernel's kWarps, known to the host).
inline int warps_per_block() { return kThreads / lx_warp_size(); }

// A lane's weight word for one step: 8 bytes, so 4 bf16 or 8 int8. The step covers LX_WARP lanes' words.
template <bool kInt8>
constexpr int kVal = kInt8 ? 8 : 4;  // values per lane per step
template <bool kInt8>
constexpr int kStep = LX_WARP * kVal<kInt8>;  // k per wavefront step
template <bool kInt8>
using WordT = uint2;

// 4 bf16 from 8 bytes. A bf16 is the top half of an f32: the low element is the low half shifted up,
// the high element is the word with its low half cleared.
__device__ __forceinline__ void decode4(uint2 v, float* f) {
  f[0] = __uint_as_float(v.x << 16);
  f[1] = __uint_as_float(v.x & 0xffff0000u);
  f[2] = __uint_as_float(v.y << 16);
  f[3] = __uint_as_float(v.y & 0xffff0000u);
}

// 8 int8 from 8 bytes.
__device__ __forceinline__ void decode8_i8(uint2 v, float* f) {
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    f[i] = static_cast<float>(static_cast<int8_t>(v.x >> (8 * i)));
    f[4 + i] = static_cast<float>(static_cast<int8_t>(v.y >> (8 * i)));
  }
}

template <bool kInt8>
__device__ __forceinline__ void decode_w(uint2 v, float* f) {
  if constexpr (kInt8) decode8_i8(v, f);
  else decode4(v, f);
}

// The lane's V x values at p as f32, V a multiple of 4. p is 16-byte aligned.
template <typename TX, int V>
__device__ __forceinline__ void load_x(const TX* p, float* f) {
  if constexpr (std::is_same_v<TX, float>) {
    const float4* q = reinterpret_cast<const float4*>(p);
#pragma unroll
    for (int i = 0; i < V / 4; ++i) {
      const float4 t = lx_ldg(q + i);
      f[4 * i] = t.x;
      f[4 * i + 1] = t.y;
      f[4 * i + 2] = t.z;
      f[4 * i + 3] = t.w;
    }
  } else {
    const uint2* q = reinterpret_cast<const uint2*>(p);
#pragma unroll
    for (int i = 0; i < V / 4; ++i) decode4(lx_ldg(q + i), f + 4 * i);
  }
}

__device__ __forceinline__ float bias_at(const void* bias, bool bias_bf16, int64_t n) {
  if (bias == nullptr) return 0.0f;
  return bias_bf16 ? lx::to_f32(static_cast<const bf16*>(bias)[n]) : static_cast<const float*>(bias)[n];
}

// Writes y = alpha * t + beta * y, where t already holds the scaled dot product plus bias. y is read
// only when beta != 0: a caller may pass an uninitialised buffer with beta = 0.
__device__ __forceinline__ void store_y(void* y, bool y_bf16, int64_t idx, float t, float alpha, float beta) {
  float v = alpha * t;
  if (beta != 0.0f) {
    const float old =
        y_bf16 ? lx::to_f32(static_cast<const bf16*>(y)[idx]) : static_cast<const float*>(y)[idx];
    v = fmaf(beta, old, v);
  }
  if (y_bf16) static_cast<bf16*>(y)[idx] = lx::from_f32<bf16>(v);
  else static_cast<float*>(y)[idx] = v;
}

// ---- vec kernel ------------------------------------------------------------------------------

// Words for the steps u_begin + u (u < KU) of rows first + r (r < RG). Steps past u_end, k past K and
// rows past N read as zero, so the consumer needs no load-side bounds handling.
template <bool kInt8, int KU, int RG>
__device__ __forceinline__ void load_steps(const void* w, int64_t first, int N, int K, int lane, int u_begin,
                                           int u_end, WordT<kInt8> (&raw)[KU][RG]) {
  using WR = WordT<kInt8>;
  constexpr int kV = kVal<kInt8>;
  constexpr int kS = kStep<kInt8>;
  const WR* words = static_cast<const WR*>(w);
#pragma unroll
  for (int u = 0; u < KU; ++u) {
    const int64_t k0 = static_cast<int64_t>(u_begin + u) * kS + kV * lane;
#pragma unroll
    for (int r = 0; r < RG; ++r) {
      raw[u][r] = WR{};
      // Streamed once per token, so they go evict-first and leave L1 to the x vector they all reuse.
      if (u_begin + u < u_end && k0 < K && first + r < N)
        raw[u][r] = lx_ldcs(words + ((first + r) * K + k0) / kV);
    }
  }
}

// Block b owns kWarps / S row groups of RG rows each. Warp w is part `w % S` of group `w / S`.
template <bool kInt8, typename TX, int RG, int S, int KU>
__global__ void __launch_bounds__(kThreads)
gemv_vec_kernel(const TX* __restrict__ x, int ld_x, const void* __restrict__ w, int K,
                const float* __restrict__ w_scale, const void* __restrict__ bias, bool bias_bf16,
                void* __restrict__ y, bool y_bf16, int ld_y, int M, int N, float alpha, float beta) {
  using WR = WordT<kInt8>;
  constexpr int kV = kVal<kInt8>;
  constexpr int kS = kStep<kInt8>;
  constexpr int kGroups = kWarps / S;
  __shared__ float partial[kWarps][RG * kMaxM];  // split-K partial sums, used when S > 1

  // Let the next kernel in the stream start its weight loads while this one runs.
  lx_pdl_trigger();
  const int warp = threadIdx.x / LX_WARP, lane = threadIdx.x & (LX_WARP - 1);
  const int group = warp / S, part = warp % S;
  const int64_t first = (static_cast<int64_t>(blockIdx.x) * kGroups + group) * RG;
  // The S warps of a group take contiguous, evenly sized runs of each row's steps.
  const int steps = (K + kS - 1) / kS;
  const int u0 = (part * steps) / S;
  const int u1 = ((part + 1) * steps) / S;

  float acc[RG][kMaxM];
#pragma unroll
  for (int r = 0; r < RG; ++r)
#pragma unroll
    for (int m = 0; m < kMaxM; ++m) acc[r][m] = 0.0f;

  // The first words go out before the dependency wait; x and y are read after it.
  WR cur[KU][RG];
  load_steps<kInt8, KU, RG>(w, first, N, K, lane, u0, u1, cur);
  lx_pdl_wait();

  // Warp-uniform guard: the whole warp takes the same branch, so the shuffles below stay full-warp.
  if (first < N) {
    for (int j = u0; j < u1; j += KU) {
      WR nxt[KU][RG];  // the next KU steps are in flight while these are consumed
      load_steps<kInt8, KU, RG>(w, first, N, K, lane, j + KU, u1, nxt);
#pragma unroll
      for (int u = 0; u < KU; ++u) {
        const int unit = j + u;
        const int64_t k0 = static_cast<int64_t>(unit) * kS + kV * lane;
        if (unit < u1 && k0 < K) {
          float wf[RG][kV];
#pragma unroll
          for (int r = 0; r < RG; ++r) decode_w<kInt8>(cur[u][r], wf[r]);
#pragma unroll
          for (int m = 0; m < kMaxM; ++m) {
            if (m < M) {
              float xf[kV];
              load_x<TX, kV>(x + static_cast<int64_t>(m) * ld_x + k0, xf);
#pragma unroll
              for (int r = 0; r < RG; ++r)
#pragma unroll
                for (int t = 0; t < kV; ++t) acc[r][m] = fmaf(wf[r][t], xf[t], acc[r][m]);
            }
          }
        }
      }
#pragma unroll
      for (int u = 0; u < KU; ++u)
#pragma unroll
        for (int r = 0; r < RG; ++r) cur[u][r] = nxt[u][r];
    }
  }

#pragma unroll
  for (int r = 0; r < RG; ++r)
#pragma unroll
    for (int m = 0; m < kMaxM; ++m)
      if (m < M) acc[r][m] = lx::warp_sum(acc[r][m]);

  if constexpr (S == 1) {
    if (lane == 0) {
#pragma unroll
      for (int r = 0; r < RG; ++r) {
        const int64_t n = first + r;
        if (n >= N) continue;
        float scale = 1.0f;
        if constexpr (kInt8) scale = w_scale[n];
        const float b = bias_at(bias, bias_bf16, n);
#pragma unroll
        for (int m = 0; m < kMaxM; ++m)
          if (m < M) store_y(y, y_bf16, static_cast<int64_t>(m) * ld_y + n, scale * acc[r][m] + b, alpha, beta);
      }
    }
  } else {
    if (lane == 0) {
#pragma unroll
      for (int r = 0; r < RG; ++r)
#pragma unroll
        for (int m = 0; m < kMaxM; ++m)
          if (m < M) partial[warp][r * kMaxM + m] = acc[r][m];
    }
    __syncthreads();  // every thread reaches this: the early-out is per group, not per block
    // Each output is summed over the S parts in a fixed order, so the result never depends on timing.
    for (int o = threadIdx.x; o < kGroups * RG * M; o += kThreads) {
      const int g = o / (RG * M), rem = o % (RG * M), r = rem / M, m = rem % M;
      const int64_t n = (static_cast<int64_t>(blockIdx.x) * kGroups + g) * RG + r;
      if (n >= N) continue;
      float sum = 0.0f;
      for (int p = 0; p < S; ++p) sum += partial[g * S + p][r * kMaxM + m];
      float scale = 1.0f;
      if constexpr (kInt8) scale = w_scale[n];
      store_y(y, y_bf16, static_cast<int64_t>(m) * ld_y + n, scale * sum + bias_at(bias, bias_bf16, n), alpha,
              beta);
    }
  }
}

// ---- small kernel ----------------------------------------------------------------------------

// One wavefront per block. It covers LX_WARP / lpr rows: lane c of a row's group of lpr lanes reads the
// e consecutive inputs starting at c * e. Scalar loads, so any stride or alignment works.
template <bool kInt8, typename TX>
__global__ void gemv_small_kernel(const TX* __restrict__ x, int ld_x, const void* __restrict__ w,
                                  const float* __restrict__ w_scale, const void* __restrict__ bias,
                                  bool bias_bf16, void* __restrict__ y, bool y_bf16, int ld_y, int M, int N,
                                  int K, int lpr, int e, float alpha, float beta) {
  lx_pdl_trigger();
  lx_pdl_wait();  // x and w may both be written by the previous kernel
  const int lane = threadIdx.x;
  const int slot = lane / lpr, c = lane % lpr;
  const int64_t n = static_cast<int64_t>(blockIdx.x) * (LX_WARP / lpr) + slot;

  float acc[kMaxM];
#pragma unroll
  for (int m = 0; m < kMaxM; ++m) acc[m] = 0.0f;
  if (n < N) {
    for (int i = 0; i < e; ++i) {
      const int k = c * e + i;
      if (k >= K) break;
      float wv;
      if constexpr (kInt8) wv = static_cast<float>(static_cast<const int8_t*>(w)[n * K + k]);
      else wv = lx::to_f32(static_cast<const bf16*>(w)[n * K + k]);
#pragma unroll
      for (int m = 0; m < kMaxM; ++m)
        if (m < M) acc[m] = fmaf(wv, lx::to_f32(x[static_cast<int64_t>(m) * ld_x + k]), acc[m]);
    }
  }

  // Sum the row's lpr lanes. The xor offsets stay inside the aligned group of lpr lanes.
  for (int off = lpr / 2; off > 0; off >>= 1)
#pragma unroll
    for (int m = 0; m < kMaxM; ++m) acc[m] += __shfl_xor_sync(LX_FULL_MASK, acc[m], off);

  if (c == 0 && n < N) {
    float scale = 1.0f;
    if constexpr (kInt8) scale = w_scale[n];
    const float b = bias_at(bias, bias_bf16, n);
#pragma unroll
    for (int m = 0; m < kMaxM; ++m)
      if (m < M) store_y(y, y_bf16, static_cast<int64_t>(m) * ld_y + n, scale * acc[m] + b, alpha, beta);
  }
}

// ---- quantizer -------------------------------------------------------------------------------

// One warp per row. The divisions are IEEE (__fdiv_rn), so q and scale match a reference that
// divides the same way.
__global__ void quantize_w8_kernel(const bf16* __restrict__ w, int8_t* __restrict__ q, float* __restrict__ scale,
                                   int64_t rows, int cols) {
  const int64_t row = static_cast<int64_t>(blockIdx.x) * kWarps + (threadIdx.x / LX_WARP);
  if (row >= rows) return;
  const int lane = threadIdx.x & (LX_WARP - 1);
  const bf16* src = w + row * cols;
  int8_t* dst = q + row * cols;

  float amax = 0.0f;
  for (int c = lane; c < cols; c += LX_WARP) amax = fmaxf(amax, fabsf(lx::to_f32(src[c])));
  amax = lx::warp_max(amax);
  // An all-zero row keeps scale 1, so it quantizes to exact zeros.
  const float s = amax > 0.0f ? __fdiv_rn(amax, 127.0f) : 1.0f;
  if (lane == 0) scale[row] = s;
  for (int c = lane; c < cols; c += LX_WARP) {
    const float r = rintf(__fdiv_rn(lx::to_f32(src[c]), s));  // rintf rounds half to even
    dst[c] = static_cast<int8_t>(static_cast<int>(fminf(fmaxf(r, -127.0f), 127.0f)));
  }
}

// ---- host side -------------------------------------------------------------------------------

struct Args {
  const void* x;
  int ld_x;
  const void* w;
  const float* w_scale;
  const void* bias;
  bool bias_bf16;
  void* y;
  bool y_bf16;
  int ld_y;
  int M, N, K;
  float alpha, beta;
  hipStream_t stream;
};

// Programmatic dependent launch: this kernel may start while the previous one in the stream drains,
// and its own grid-dependency wait holds back everything that reads what that kernel wrote.
lx_launch_config pdl_config(unsigned blocks, int threads, hipStream_t stream, lx_launch_attr& attr) {
  lx_launch_config cfg{};
  cfg.gridDim = dim3(blocks);
  cfg.blockDim = dim3(threads);
  cfg.dynamicSmemBytes = 0;
  cfg.stream = stream;
  attr.id = LX_LAUNCH_ATTR_PDL;
  attr.val.programmaticStreamSerializationAllowed = 1;
  cfg.attrs = &attr;
  cfg.numAttrs = 1;
  return cfg;
}

template <bool kInt8, typename TX>
hipError_t launch_small(const Args& a) {
  // Lanes per row: the smallest power of two (at most a wavefront) that gives each lane at most 8 inputs.
  const int w = lx_warp_size();
  int lpr = 1;
  while (lpr < w && lpr * 8 < a.K) lpr *= 2;
  const int e = (a.K + lpr - 1) / lpr;
  const int rows_per_warp = w / lpr;
  const unsigned blocks = static_cast<unsigned>((a.N + rows_per_warp - 1) / rows_per_warp);
  lx_launch_attr attr{};
  const lx_launch_config cfg = pdl_config(blocks, w, a.stream, attr);
  return lx_launch_kernel_ex(&cfg, gemv_small_kernel<kInt8, TX>, static_cast<const TX*>(a.x), a.ld_x, a.w, a.w_scale,
                     a.bias, a.bias_bf16, a.y, a.y_bf16, a.ld_y, a.M, a.N, a.K, lpr, e, a.alpha, a.beta);
}

template <bool kInt8, typename TX, int RG, int S, int KU>
hipError_t run_vec(const Args& a) {
  const int kGroups = warps_per_block() / S;  // S <= the block's wavefronts (dispatch_vec checks)
  const int64_t rows_per_block = static_cast<int64_t>(kGroups) * RG;
  const unsigned blocks = static_cast<unsigned>((a.N + rows_per_block - 1) / rows_per_block);
  lx_launch_attr attr{};
  const lx_launch_config cfg = pdl_config(blocks, kThreads, a.stream, attr);
  return lx_launch_kernel_ex(&cfg, gemv_vec_kernel<kInt8, TX, RG, S, KU>, static_cast<const TX*>(a.x), a.ld_x, a.w, a.K,
                     a.w_scale, a.bias, a.bias_bf16, a.y, a.y_bf16, a.ld_y, a.M, a.N, a.alpha, a.beta);
}

// The vec kernel's shape for one launch. S warps split each row's steps when N is too small to keep
// kWarpTarget warps busy. The rest is from the sweep on the 5070 Ti.
struct VecConfig {
  int S;   // warps per row group
  int RG;  // rows per warp
  int KU;  // steps whose loads are in flight per warp
};

VecConfig choose_vec(int N, int K, int M, bool int8) {
  const int step = lx_warp_size() * (int8 ? 8 : 4);
  const int steps = (K + step - 1) / step;
  int S = 1;
  while (S < 8 && S < warps_per_block() && static_cast<int64_t>(N) * S < kWarpTarget && steps / (2 * S) >= 1) S *= 2;
  // Rows per warp and steps in flight, from the sweep. At M = 1 a warp that owns the whole row takes
  // two rows, so one x load serves both; split rows already have enough warps in flight.
  int RG = 1;
  int KU = 2;
  if (int8 && M == 1) {
    RG = S == 1 ? 2 : 1;
    KU = 1;
  }
  while (KU > 1 && KU > steps / S) KU /= 2;
  return VecConfig{S, RG, KU};
}

// Dispatch to the instantiation for (S, RG, KU). Only these combinations are built.
template <bool kInt8, typename TX>
hipError_t dispatch_vec(const Args& a, const VecConfig& c) {
  if (c.S > warps_per_block()) return hipErrorInvalidValue;
#define LX_VEC_CASE(S_, RG_, KU_) \
  if (c.S == S_ && c.RG == RG_ && c.KU == KU_) return run_vec<kInt8, TX, RG_, S_, KU_>(a);
  LX_VEC_CASE(1, 1, 1) LX_VEC_CASE(1, 1, 2) LX_VEC_CASE(1, 1, 4) LX_VEC_CASE(1, 2, 1)
  LX_VEC_CASE(2, 1, 1) LX_VEC_CASE(2, 1, 2) LX_VEC_CASE(2, 1, 4)
  LX_VEC_CASE(4, 1, 1) LX_VEC_CASE(4, 1, 2) LX_VEC_CASE(4, 1, 4)
  LX_VEC_CASE(8, 1, 1) LX_VEC_CASE(8, 1, 2) LX_VEC_CASE(8, 1, 4)
#undef LX_VEC_CASE
  return hipErrorInvalidValue;
}

template <bool kInt8, typename TX>
hipError_t launch_vec(const Args& a) {
  return dispatch_vec<kInt8, TX>(a, choose_vec(a.N, a.K, a.M, kInt8));
}

template <bool kInt8, typename TX>
hipError_t launch(const Args& a) {
  // Vector loads need 16-byte alignment: the weight base, and the x base and row stride. K must be a
  // multiple of the lane's values per step, so each lane's word is whole within its row.
  const bool aligned = reinterpret_cast<uintptr_t>(a.w) % 16 == 0 &&
                       ((reinterpret_cast<uintptr_t>(a.x) | (static_cast<uint64_t>(a.ld_x) * sizeof(TX))) % 16 == 0);
  if (a.K <= kSmallK || a.K % kVal<kInt8> != 0 || !aligned) return launch_small<kInt8, TX>(a);
  return launch_vec<kInt8, TX>(a);
}

bool valid_dtype(lx_dtype d) { return d == LX_F32 || d == LX_BF16; }



}  // namespace

extern "C" int lx_gemv(const void* x, lx_dtype x_dtype, int ld_x, const void* w, lx_wtype w_type, const float* w_scale,
                       const void* bias, lx_dtype bias_dtype, void* y, lx_dtype y_dtype, int ld_y, int M, int N, int K,
                       float alpha, float beta, void* stream) {
  if (M == 0 || N == 0) return 0;
  if (M < 0 || M > kMaxM || K <= 0 || ld_x < K || ld_y < N) return static_cast<int>(hipErrorInvalidValue);
  if (!valid_dtype(x_dtype) || !valid_dtype(y_dtype) || !valid_dtype(bias_dtype)) return static_cast<int>(hipErrorInvalidValue);
  if (w_type != LX_W_BF16 && w_type != LX_W_INT8) return static_cast<int>(hipErrorInvalidValue);
  if (!x || !w || !y || (w_type == LX_W_INT8 && !w_scale)) return static_cast<int>(hipErrorInvalidValue);

  const Args a{
      .x = x,
      .ld_x = ld_x,
      .w = w,
      .w_scale = w_scale,
      .bias = bias,
      .bias_bf16 = bias_dtype == LX_BF16,
      .y = y,
      .y_bf16 = y_dtype == LX_BF16,
      .ld_y = ld_y,
      .M = M,
      .N = N,
      .K = K,
      .alpha = alpha,
      .beta = beta,
      .stream = static_cast<hipStream_t>(stream),
  };
  hipError_t e;
  if (w_type == LX_W_INT8) {
    e = x_dtype == LX_BF16 ? launch<true, bf16>(a) : launch<true, float>(a);
  } else {
    e = x_dtype == LX_BF16 ? launch<false, bf16>(a) : launch<false, float>(a);
  }
  return static_cast<int>(e);
}

extern "C" int lx_quantize_w8(const void* w, int8_t* q, float* scale, int64_t rows, int cols, void* stream) {
  if (rows <= 0) return 0;
  if (cols <= 0 || !w || !q || !scale) return static_cast<int>(hipErrorInvalidValue);
  const int64_t blocks = (rows + warps_per_block() - 1) / warps_per_block();
  quantize_w8_kernel<<<static_cast<unsigned int>(blocks), kThreads, 0, static_cast<hipStream_t>(stream)>>>(
      static_cast<const bf16*>(w), q, scale, rows, cols);
  return lx::launch_status();
}
